import { randomFrom } from './learning.js';
export function matchRules(rules, packet) {
  for (const rule of rules) if (['source', 'destination', 'port'].every(key => rule[key] === 'any' || rule[key] === packet[key])) return { ruleId: rule.id, action: rule.action };
  return { ruleId: null, action: 'deny' };
}
export function firewallScenario(seed, order = 'deny-first') {
  const random = randomFrom(seed);
  const packet = { source: random() < .6 ? '198.51.100.27' : '203.0.113.42', destination: random() < .8 ? '192.0.2.10' : '192.0.2.20', port: random() < .7 ? 443 : 22 };
  const deny = { id: 'blocked-source', source: '198.51.100.27', destination: 'any', port: 'any', action: 'deny', label: '198.51.100.27에서 오는 모든 연결 차단' };
  const allow = { id: 'public-web', source: 'any', destination: '192.0.2.10', port: 443, action: 'allow', label: '웹 서버 192.0.2.10의 443번 포트 허용' };
  const rules = [...(order === 'deny-first' ? [deny, allow] : [allow, deny]), { id: 'default-deny', source: 'any', destination: 'any', port: 'any', action: 'deny', label: '나머지 모든 연결 차단' }];
  return { packet, rules, result: matchRules(rules, packet) };
}
export function classifyDetection(detected, isAttack) { return detected ? isAttack ? '정탐' : '오탐' : isAttack ? '미탐' : '정상 판정'; }
export function correlationMatches(events, { start, end, minimum, targets }) {
  const grouped = new Map();
  for (const event of events) if (event.at >= start && event.at < end) { if (!grouped.has(event.source)) grouped.set(event.source, []); grouped.get(event.source).push(event); }
  return [...grouped].filter(([, list]) => list.length >= minimum && new Set(list.map(e => e.target)).size >= targets).map(([source]) => source);
}
